package com.ruoyi.web.controller.shop;
import java.io.*;import java.util.*;import javax.servlet.http.HttpServletRequest;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import org.springframework.http.*;import org.apache.poi.xssf.usermodel.XSSFWorkbook;import org.apache.poi.ss.usermodel.*;import com.alibaba.fastjson2.*;import com.ruoyi.common.annotation.Anonymous;import com.ruoyi.common.core.domain.AjaxResult;import static com.ruoyi.web.controller.shop.ShopService.*;
@Anonymous @RestController @RequestMapping("/shop/app/procurement") public class ShopProcurementController {
 @Autowired ShopService s;@Autowired ShopGrades grades;
 private Map<String,Object> buyer(HttpServletRequest r){Map<String,Object> m=s.member(r.getHeader("X-Shop-Token"));s.companyPurchase(number(m.get("id")));return m;}
 @GetMapping("/template") public ResponseEntity<byte[]> template(HttpServletRequest r)throws IOException {Map<String,Object> m=buyer(r);long certified=number(m.get("company_pricing_member"));try(XSSFWorkbook book=new XSSFWorkbook();ByteArrayOutputStream out=new ByteArrayOutputStream()){Sheet sheet=book.createSheet("采购清单");String[] headers={"商品编码","采购数量","商品名称","规格","至少采购","采购倍数","参考单价（元）"};Row h=sheet.createRow(0);for(int i=0;i<headers.length;i++)h.createCell(i).setCellValue(headers[i]);int row=1;for(Map<String,Object> p:s.catalogProducts(number(m.get("id")),certified)){Row line=sheet.createRow(row++);line.createCell(0).setCellValue(str(p.get("product_code")));line.createCell(1).setCellValue(0);line.createCell(2).setCellValue(str(p.get("name")));line.createCell(3).setCellValue(str(p.get("spec")));line.createCell(4).setCellValue(number(p.get("minimum")));line.createCell(5).setCellValue(number(p.get("pack")));line.createCell(6).setCellValue(number(p.get("wholesale"))/100.0);}for(int i=0;i<headers.length;i++)sheet.setColumnWidth(i,(i==2?35:20)*256);sheet.createFreezePane(0,1);Sheet note=book.createSheet("填写说明");note.createRow(0).createCell(0).setCellValue("只填写采购数量；0或留空表示不采购。每次最多100种商品。价格、起订和库存以导入预览及下单确认时为准。");note.setColumnWidth(0,100*256);book.write(out);return ResponseEntity.ok().cacheControl(CacheControl.noStore()).header("Content-Disposition","attachment; filename=procurement.xlsx").contentType(MediaType.parseMediaType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")).body(out.toByteArray());}}
 @GetMapping("/frequent") public AjaxResult frequent(HttpServletRequest r){Map<String,Object> m=buyer(r);long uid=number(m.get("id"));return AjaxResult.success(s.jdbc().queryForList("select i.product_id,sum(i.quantity) purchased_quantity from shop_order_item i join shop_order o on o.id=i.order_id where o.channel='B' and o.paid_at is not null and o.status<>'refunded' and "+s.companyOrderScope(uid)+" group by i.product_id order by purchased_quantity desc limit 100"));}
 @GetMapping("/orders/{id}/document") public ResponseEntity<byte[]> document(HttpServletRequest r,@PathVariable long id)throws IOException{long uid=number(s.member(r.getHeader("X-Shop-Token")).get("id"));Map<String,Object> o=s.companyOrder(uid,id,"view",false);check("B".equals(o.get("channel")),"请选择采购订单");JSONObject address=JSON.parseObject(str(o.get("address_json")));try(XSSFWorkbook wb=new XSSFWorkbook();ByteArrayOutputStream out=new ByteArrayOutputStream()){Sheet sh=wb.createSheet("采购单");String[] info={"采购订单 "+str(o.get("order_no")),"下单时间："+str(o.get("created_at")),"收货人："+str(address.get("name"))+"  "+str(address.get("phone")),"收货地址："+str(address.get("address")),"按下单快照出具，非发票；订单编号可用于后台核对"};for(int n=0;n<info.length;n++){sh.createRow(n).createCell(0).setCellValue(info[n]);sh.addMergedRegion(new org.apache.poi.ss.util.CellRangeAddress(n,n,0,4));}String[] head={"商品","规格","数量","单价（元）","商品小计（元）"};Row h=sh.createRow(6);for(int n=0;n<5;n++)h.createCell(n).setCellValue(head[n]);int row=7;for(Map<String,Object> i:s.jdbc().queryForList("select * from shop_order_item where order_id=? order by id",id)){Row line=sh.createRow(row++);line.createCell(0).setCellValue(str(i.get("name")));line.createCell(1).setCellValue(str(i.get("spec")));line.createCell(2).setCellValue(number(i.get("quantity")));line.createCell(3).setCellValue(number(i.get("price"))/100.0);line.createCell(4).setCellValue(number(i.get("price"))*number(i.get("quantity"))/100.0);}String[] keys={"discount","shipping_amount","amount","refunded_amount"},labels={"优惠","运费","订单应付","已退款"};for(int n=0;n<keys.length;n++){Row line=sh.createRow(row++);line.createCell(0).setCellValue(labels[n]+"（元）");line.createCell(4).setCellValue(number(o.get(keys[n]))/100.0);}sh.createRow(row).createCell(0).setCellValue("应付金额不代表已经付款，实际状态以订单为准。");for(int n=0;n<5;n++)sh.setColumnWidth(n,(n==0?32:n==1?22:18)*256);sh.getPrintSetup().setPaperSize(PrintSetup.A4_PAPERSIZE);sh.getPrintSetup().setFitWidth((short)1);sh.getPrintSetup().setFitHeight((short)0);sh.setFitToPage(true);sh.setRepeatingRows(new org.apache.poi.ss.util.CellRangeAddress(6,6,-1,-1));wb.write(out);return ResponseEntity.ok().cacheControl(CacheControl.noStore()).header("Content-Disposition","attachment; filename=purchase-"+id+".xlsx").contentType(MediaType.parseMediaType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")).body(out.toByteArray());}}
 private long cell(Cell cell,boolean optional){if(cell==null||cell.getCellType()==CellType.BLANK)return optional?0:-1;check(cell.getCellType()!=CellType.FORMULA,"请填写数值，不使用公式");String text=cell.getCellType()==CellType.NUMERIC?java.math.BigDecimal.valueOf(cell.getNumericCellValue()).stripTrailingZeros().toPlainString():new DataFormatter().formatCellValue(cell).trim();if(text.isEmpty()&&optional)return 0;return integer(text,optional?0:1,optional?10000:Long.MAX_VALUE,"编号和数量必须是有效整数");}
 @PostMapping("/preview") public AjaxResult preview(HttpServletRequest r,@RequestParam("file")MultipartFile file)throws IOException {Map<String,Object> m=buyer(r);check(file.getSize()>0&&file.getSize()<=5*1024*1024,"请上传5MB以内的xlsx表格");List<String> errors=new ArrayList<>();Map<Long,Long> counts=new LinkedHashMap<>();try(XSSFWorkbook book=new XSSFWorkbook(file.getInputStream())){check(book.getNumberOfSheets()>0,"表格没有工作表");Sheet sheet=book.getSheetAt(0);check(sheet.getLastRowNum()<=10000,"表格最多10000行");check(sheet.getRow(0)!=null&&Arrays.asList("商品编号","商品编码").contains(new DataFormatter().formatCellValue(sheet.getRow(0).getCell(0)))&&"采购数量".equals(new DataFormatter().formatCellValue(sheet.getRow(0).getCell(1))),"请使用下载的采购模板，不要修改前两列标题");for(int row=1;row<=sheet.getLastRowNum();row++){Row line=sheet.getRow(row);if(line==null)continue;try{long quantity=cell(line.getCell(1),true);if(quantity==0)continue;Cell codeCell=line.getCell(0);check(codeCell!=null&&codeCell.getCellType()!=CellType.FORMULA,"请填写商品编码，不使用公式");String code=new DataFormatter().formatCellValue(codeCell).trim();long id="商品编号".equals(new DataFormatter().formatCellValue(sheet.getRow(0).getCell(0)))?cell(codeCell,false):number(s.one("select id from shop_product where product_code=?",code).get("id")),total=counts.getOrDefault(id,0L)+quantity;check(total<=10000,"合计数量不能超过10000件");counts.put(id,total);}catch(IllegalArgumentException e){errors.add("第"+(row+1)+"行："+e.getMessage());}if(errors.size()>=100)break;}}
 check(counts.size()<=100,"每次最多导入100种商品，请拆分清单");JSONArray items=new JSONArray();for(Map.Entry<Long,Long> item:counts.entrySet()){try{Map<String,Object> p=s.one("select * from shop_product where id=?",item.getKey());check(Boolean.TRUE.equals(p.get("enabled"))||"1".equals(str(p.get("enabled"))),"商品已下架");check(Boolean.TRUE.equals(p.get("wholesale_enabled"))||"1".equals(str(p.get("wholesale_enabled"))),"商品未开放采购");check(s.channelStock(item.getKey(),"B")>=item.getValue(),"采购渠道库存不足");grades.validate(p,number(m.get("company_pricing_member")),item.getValue());Map<String,Object> price=grades.purchase(p,number(m.get("company_pricing_member")),item.getValue());JSONObject result=new JSONObject();result.put("id",item.getKey());result.put("name",p.get("name"));result.put("spec",p.get("spec"));result.put("quantity",item.getValue());result.put("price",price.get("price"));result.put("basis",price.get("basis"));result.put("checked",true);items.add(result);}catch(IllegalArgumentException e){errors.add("商品"+item.getKey()+"："+e.getMessage());}}
 JSONObject out=new JSONObject();out.put("items",items);out.put("errors",errors);return AjaxResult.success(out);}
}
